<script setup lang="ts">
import {computed} from 'vue'
import {useRoute} from 'vue-router'
import {supabase} from './services/supabase'
import {cloudAuth} from './services/cloudbase'
import {store} from './stores/community'
const route=useRoute()
const referenceLayout=computed(()=>['/','/outing','/community','/publish','/goods','/profile'].includes(route.path)||route.path.startsWith('/posts/')||route.path.startsWith('/goods/'))
if(supabase){supabase.auth.getSession().then(({data})=>{store.profile=data.session?{id:data.session.user.id,name:store.profile?.id===data.session.user.id?store.profile.name:(data.session.user.user_metadata.name||'铲屎官'),email:data.session.user.email||''}:null});supabase.auth.onAuthStateChange((_event,session)=>{store.profile=session?{id:session.user.id,name:store.profile?.id===session.user.id?store.profile.name:(session.user.user_metadata.name||'铲屎官'),email:session.user.email||''}:null})}
</script>
<template><div class="app-shell" :class="{'reference-shell':referenceLayout}"><div v-if="!referenceLayout" class="mode-note">前端体验版 · {{cloudAuth?'PawsUp · 云端同步':supabase?'Supabase 认证 · 宠物档案云端同步':'本地演示数据'}} </div><RouterView/><nav v-if="referenceLayout&&route.path!=='/publish'&&!route.path.startsWith('/goods/')" class="ref-bottom" aria-label="主导航"><RouterLink to="/" :class="{active:route.path==='/'}" :aria-current="route.path==='/'?'page':undefined"><van-icon name="wap-home-o"/><span>首页</span></RouterLink><RouterLink to="/outing" :class="{active:route.path==='/outing'}" :aria-current="route.path==='/outing'?'page':undefined"><van-icon name="search"/><span>出行</span></RouterLink><RouterLink to="/community" :class="{active:(route.path==='/community'||route.path==='/publish'||route.path.startsWith('/posts/'))}" :aria-current="(route.path==='/community'||route.path==='/publish'||route.path.startsWith('/posts/'))?'page':undefined"><van-icon name="bell"/><span>社区</span></RouterLink><RouterLink to="/goods" :class="{active:route.path==='/goods'}" :aria-current="route.path==='/goods'?'page':undefined"><van-icon name="setting-o"/><span>好物</span></RouterLink><RouterLink to="/profile" :class="{active:route.path==='/profile'}" :aria-current="route.path==='/profile'?'page':undefined"><van-icon name="user-o"/><span>我的</span></RouterLink></nav><van-tabbar v-else-if="route.path!=='/auth'&&route.path!=='/publish'&&!route.path.startsWith('/goods/')" route active-color="#a15f9b" inactive-color="#8c809b" fixed safe-area-inset-bottom><van-tabbar-item to="/" icon="wap-home-o">首页</van-tabbar-item><van-tabbar-item to="/community" icon="friends-o">社区</van-tabbar-item><van-tabbar-item to="/publish" icon="add-o">发布</van-tabbar-item><van-tabbar-item to="/pets" icon="smile-o">毛孩子</van-tabbar-item><van-tabbar-item to="/profile" icon="user-o">我的</van-tabbar-item></van-tabbar></div></template>
